const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const plumePoint = ee.Geometry.Point(-136.275745, 69.264212);
    const oceanPoint = ee.Geometry.Point(-137.786365, 69.803894);

    const startDate = '2017-07-19';
    const endDate = '2017-07-20'; // Exact date, so end date is the day after.

    // 2. Data Acquisition
    let s2_collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(plumePoint.buffer(10000).merge(oceanPoint.buffer(10000))) // Filter by a broader area
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Keep relatively clear images

    // Check if collection is empty
    if (s2_collection.size().getInfo() === 0) {
      console.log("No Sentinel-2 SR images found for July 19, 2017, with <20% cloud cover.");
      console.log("Attempting to widen date range to +/- 2 days...");
      const widerStartDate = '2017-07-17';
      const widerEndDate = '2017-07-22';
      s2_collection = ee.ImageCollection('COPERNICUS/S2_SR')
        .filterBounds(plumePoint.buffer(10000).merge(oceanPoint.buffer(10000)))
        .filterDate(widerStartDate, widerEndDate)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

      if (s2_collection.size().getInfo() === 0) {
        console.log("No images found even after widening the date range.");
        console.log("C1");
        return;
      }
    }

    // Sort by cloudiness and take the least cloudy image
    const image = s2_collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();
    if (!image) { // This should ideally be caught by size().getInfo() == 0, but as a safeguard
      console.log("C1");
      return;
    }

    const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();
    const cloudPercentage = image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();
    console.log(`Using image: ${image.id().getInfo()} (Date: ${imageDate}, Cloud Cover: ${cloudPercentage.toFixed(2)}%)`);

    // Masking function for Sentinel-2 SR (SCL band)
    function maskS2sr(image) {
      const sgl = image.select('SCL');
      // Pixels with values 3 (cloud shadow), 8 (cloud medium probability), 9 (cloud high probability), 10 (cirrus)
      // are considered cloudy/invalid.
      const cloudMask = sgl.updateMask(sgl.neq(3).and(sgl.neq(8)).and(sgl.neq(9)).and(sgl.neq(10)));
      return image.updateMask(cloudMask);
    }

    const maskedImage = maskS2sr(image);

    // 3. Processing - Extract Blue band (B2) reflectance for 'milky' appearance
    // B2 (Blue) is often a good indicator for suspended sediment in water
    const band = 'B2';
    const scale = 10; // Sentinel-2 B2 resolution is 10m

    // Calculate mean B2 reflectance for plume point
    const plumeStats = maskedImage.select(band).reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: plumePoint.buffer(50), // Use a small buffer to get local average
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    // Calculate mean B2 reflectance for ocean point
    const oceanStats = maskedImage.select(band).reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: oceanPoint.buffer(50), // Use a small buffer
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const plumeB2 = plumeStats[band + '_mean'];
    const plumePixels = plumeStats[band + '_count'];
    const oceanB2 = oceanStats[band + '_mean'];
    const oceanPixels = oceanStats[band + '_count'];

    // Check for C2 (No Valid Pixels)
    if (plumePixels === 0 || oceanPixels === 0) {
      console.log(`Plume Pixels: ${plumePixels}, Ocean Pixels: ${oceanPixels}`);
      console.log("No valid pixels remain after masking for one or both locations.");
      console.log("C2");
      return;
    }

    // Check for C3 (Calculation Failure - None, NaN, etc.)
    if (plumeB2 === null || oceanB2 === null || isNaN(plumeB2) || isNaN(oceanB2)) {
      console.log(`Plume B2 Mean: ${plumeB2}, Ocean B2 Mean: ${oceanB2}`);
      console.log("Calculation resulted in None/NaN for one or both points.");
      console.log("C3");
      return;
    }

    // 4. Comparison and Final Answer
    console.log(`Plume (B2 reflectance): ${plumeB2.toFixed(2)} (Pixels: ${plumePixels})`);
    console.log(`Ocean (B2 reflectance): ${oceanB2.toFixed(2)} (Pixels: ${oceanPixels})`);

    // A higher B2 reflectance implies more suspended sediment, thus 'milky' appearance
    if (plumeB2 > oceanB2) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("Analysis failed:", error);
    if (error.message.includes("does not exist") || error.message.includes("Invalid band")) {
        console.log("D"); // Incorrect image, collection, or band names, syntax error.
    } else {
        console.log("D"); // General error implying a code issue or unexpected GEE behavior.
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
